    "mahjong.roundEnd.noWinnerTitle": { "pt-BR": "Mão encerrada sem vencedor", en: "Hand over — no winner", zh: "本局结束，无人胡牌", fr: "Manche terminée sans gagnant", es: "Mano finalizada sin ganador" },
    "mahjong.roundEnd.noWinnerStats": { "pt-BR": "O monte acabou antes de alguém fechar a mão.", en: "The wall ran out before anyone completed their hand.", zh: "牌墙已空，无人和牌。", fr: "Le mur s'est épuisé avant que quelqu'un ne termine sa main.", es: "El monte se acabó antes de que alguien cerrara la mano." },
    "mahjong.roundEnd.youWonTitle": { "pt-BR": "Você fechou a mão! Hu! 🎉", en: "You won the hand! Hu! 🎉", zh: "你和牌了！胡！🎉", fr: "Vous avez terminé la main ! Hu ! 🎉", es: "¡Cerraste la mano! ¡Hu! 🎉" },
    "mahjong.roundEnd.wonByTitle": { "pt-BR": "{name} fechou a mão!", en: "{name} won the hand!", zh: "{name} 和牌了！", fr: "{name} a terminé la main !", es: "¡{name} cerró la mano!" },
    "mahjong.roundEnd.zimo": { "pt-BR": "Vitória por compra própria (zimo).", en: "Won by self-draw (zimo).", zh: "自摸获胜。", fr: "Victoire par pioche personnelle (zimo).", es: "Victoria por robo propio (zimo)." },
    "mahjong.roundEnd.fromDiscard": { "pt-BR": "Vitória no descarte de {name}.", en: "Won off {name}'s discard.", zh: "以 {name} 的弃牌胡牌。", fr: "Victoire sur la défausse de {name}.", es: "Victoria con el descarte de {name}." },
    "mahjong.hint.onlyOnTurn": { "pt-BR": "Só dá pra sugerir na sua vez de descartar.", en: "You can only get a suggestion on your turn to discard.", zh: "只能在轮到你出牌时获取建议。", fr: "Vous ne pouvez obtenir une suggestion qu'à votre tour de défausser.", es: "Solo puedes pedir sugerencia en tu turno de descartar." },
    "mahjong.hint.noGroupsYet": { "pt-BR": "nenhum grupo formado ainda", en: "no groups formed yet", zh: "尚未组成任何牌组", fr: "aucun groupe formé pour l'instant", es: "ningún grupo formado todavía" },
    "mahjong.hint.suggestion": { "pt-BR": "Sugestão: descarte {tile}. Você já tem: {groups}.", en: "Suggestion: discard {tile}. You already have: {groups}.", zh: "建议：打出 {tile}。你已经有：{groups}。", fr: "Suggestion : défaussez {tile}. Vous avez déjà : {groups}.", es: "Sugerencia: descarta {tile}. Ya tienes: {groups}." },
    "mahjong.group.triplet": { "pt-BR": "Trinca formada", en: "Triplet formed", zh: "已成刻子", fr: "Brelan formé", es: "Trío formado" },
