    "mahjong.tileInfo.triplet": { "pt-BR": "Já forma uma trinca ({values} {suit}). Já conta como um dos 4 grupos — pode ainda virar Kong se comprar/reagir à 4ª igual.", en: "Already forms a triplet ({values} {suit}). Already counts as one of the 4 sets — can still become a Kong if you draw/claim the 4th matching tile.", zh: "已经组成刻子（{values} {suit}）。已算作4组之一——若再摸到/吃到第4张相同的牌，还能变成杠。", fr: "Forme déjà un brelan ({values} {suit}). Compte déjà comme l'un des 4 groupes — peut encore devenir un Kong si vous piochez/réclamez la 4e tuile identique.", es: "Ya forma un trío ({values} {suit}). Ya cuenta como uno de los 4 grupos — aún puede volverse Kong si robas/reclamas la 4ª ficha igual." },
    "mahjong.tileInfo.run": { "pt-BR": "Já faz parte de uma sequência completa ({values} {suit}). Já conta como um dos 4 grupos.", en: "Already part of a complete run ({values} {suit}). Already counts as one of the 4 sets.", zh: "已经是完整顺子的一部分（{values} {suit}）。已算作4组之一。", fr: "Fait déjà partie d'une séquence complète ({values} {suit}). Compte déjà comme l'un des 4 groupes.", es: "Ya forma parte de una escalera completa ({values} {suit}). Ya cuenta como uno de los 4 grupos." },
    "mahjong.tileInfo.pair": { "pt-BR": "Já forma o par da mão ({value} {suit}). Você só precisa de 1 par no total — não precisa de mais peças iguais a essa.", en: "Already forms the hand's pair ({value} {suit}). You only need 1 pair total — you don't need more tiles matching this one.", zh: "已经组成本手牌的对子（{value} {suit}）。你总共只需要1对——不需要更多和它一样的牌。", fr: "Forme déjà la paire de la main ({value} {suit}). Vous n'avez besoin que d'1 paire au total — pas besoin de plus de tuiles identiques.", es: "Ya forma el par de la mano ({value} {suit}). Solo necesitas 1 par en total — no necesitas más fichas iguales a esta." },
    "mahjong.tileInfo.partialRun": { "pt-BR": "Sequência parcial ({values} {suit}). Falta comprar/reagir a: {waits}.", en: "Partial run ({values} {suit}). Still need to draw/claim: {waits}.", zh: "顺子差一张（{values} {suit}）。还需要摸到/吃到：{waits}。", fr: "Séquence partielle ({values} {suit}). Il manque encore à piocher/réclamer : {waits}.", es: "Escalera parcial ({values} {suit}). Falta robar/reclamar: {waits}." },
    "mahjong.tileInfo.isolated": { "pt-BR": "Peça isolada, ainda sem grupo. Vira Par se comprar/reagir a outra {value} {suit}, ou entra numa sequência com peças próximas ({waits} {suit}).", en: "Isolated tile, no group yet. Becomes a Pair if you draw/claim another {value} {suit}, or joins a run with nearby tiles ({waits} {suit}).", zh: "孤立的牌，还未组成牌组。若摸到/吃到另一张 {value} {suit} 可组成对子，或与附近的牌（{waits} {suit}）组成顺子。", fr: "Tuile isolée, sans groupe pour l'instant. Devient une Paire si vous piochez/réclamez une autre {value} {suit}, ou rejoint une séquence avec des tuiles proches ({waits} {suit}).", es: "Ficha aislada, aún sin grupo. Se vuelve Par si robas/reclamas otra {value} {suit}, o entra en una escalera con fichas cercanas ({waits} {suit})." },
    "mahjong.tileInfo.or": { "pt-BR": " ou ", en: " or ", zh: "或", fr: " ou ", es: " o " },
    "mahjong.multiplier.withNotes": { "pt-BR": "Multiplicador estimado se fechar com essa cara: ×{mult} ({notes}).", en: "Estimated multiplier if you close with this shape: ×{mult} ({notes}).", zh: "若以此牌型胡牌，预估倍数：×{mult}（{notes}）。", fr: "Multiplicateur estimé si vous terminez avec cette configuration : ×{mult} ({notes}).", es: "Multiplicador estimado si cierras con esta forma: ×{mult} ({notes})." },
    "mahjong.multiplier.none": { "pt-BR": "Multiplicador estimado: ×{mult} (sem bônus especial ainda).", en: "Estimated multiplier: ×{mult} (no special bonus yet).", zh: "预估倍数：×{mult}（暂无特殊加成）。", fr: "Multiplicateur estimé : ×{mult} (pas encore de bonus spécial).", es: "Multiplicador estimado: ×{mult} (sin bono especial todavía)." },
    "mahjong.multiplier.pengpeng": { "pt-BR": "Pong Pong Hu (só trincas) ×2", en: "Pong Pong Hu (all triplets) ×2", zh: "碰碰胡（全刻子）×2", fr: "Pong Pong Hu (que des brelans) ×2", es: "Pong Pong Hu (solo tríos) ×2" },
    "mahjong.multiplier.oneSuit": { "pt-BR": "Um naipe só (清一色) ×2", en: "Single suit (清一色) ×2", zh: "清一色 ×2", fr: "Une seule couleur (清一色) ×2", es: "Un solo palo (清一色) ×2" },
    "mahjong.multiplier.concealed": { "pt-BR": "Mão fechada (门清) ×2", en: "Concealed hand (门清) ×2", zh: "门清 ×2", fr: "Main cachée (门清) ×2", es: "Mano cerrada (门清) ×2" },
