    "mahjong.err.kongEmptyWall": { "pt-BR": "Não dá para declarar Kong: o monte está vazio, não há peça de reposição para comprar.", en: "Can't declare Kong: the wall is empty, there's no replacement tile to draw.", zh: "无法宣告杠：牌墙已空，没有牌可以补摸。", fr: "Impossible de déclarer Kong : le mur est vide, il n'y a pas de tuile de remplacement à piocher.", es: "No se puede declarar Kong: el monte está vacío, no hay ficha de reposición para robar." },
