    "mahjong.err.noPendingClaim": { "pt-BR": "Nenhum descarte para reagir.", en: "No discard to react to.", zh: "没有可以反应的弃牌。", fr: "Aucune défausse à laquelle réagir.", es: "Ningún descarte al cual reaccionar." },
