    "puzzle.lobby.roomCodePlaceholder": { "pt-BR": "ex: QUEBRA1", en: "e.g. PUZZLE1", zh: "例如：PUZZLE1", fr: "ex. PUZZLE1", es: "ej: PUZZLE1" },
    "puzzle.lobby.playLocal": { "pt-BR": "Montar sozinho (sem servidor)", en: "Assemble solo (no server)", zh: "单人拼图（无需服务器）", fr: "Assembler seul (sans serveur)", es: "Armar solo (sin servidor)" },
    "puzzle.lobby.hint": {
      "pt-BR": "Até 8 pessoas por sala, todo mundo arrasta peças ao mesmo tempo. Alguém envia uma foto, escolhe o tamanho da grade e as peças são cortadas com bordas onduladas geradas por uma cadeia de Markov (cada peça sai diferente, mas encaixa perfeitamente na vizinha).",
      en: "Up to 8 people per room, everyone drags pieces at the same time. Someone uploads a photo, picks the grid size, and the pieces are cut with wavy edges generated by a Markov chain (each piece comes out different, but fits its neighbor perfectly).",
      zh: "每个房间最多8人，大家可以同时拖动拼块。有人上传照片，选择网格大小，拼块的波浪边缘由马尔可夫链生成（每块都不同，但与相邻块完美契合）。",
      fr: "Jusqu'à 8 personnes par salle, tout le monde fait glisser des pièces en même temps. Quelqu'un téléverse une photo, choisit la taille de la grille, et les pièces sont découpées avec des bords ondulés générés par une chaîne de Markov (chaque pièce est différente, mais s'emboîte parfaitement avec sa voisine).",
      es: "Hasta 8 personas por sala, todos arrastran piezas al mismo tiempo. Alguien sube una foto, elige el tamaño de la cuadrícula y las piezas se cortan con bordes ondulados generados por una cadena de Markov (cada pieza sale distinta, pero encaja perfecto con su vecina).",
    },
